changeSet.sql:
CREATE TABLE IF NOT EXISTS "animals"."animaltype"(
"id"           bigint not null primary key,
"animaltype"   varchar(255)
);

CREATE TABLE IF NOT EXISTS "animals"."animal"(
"id"           bigint not null primary key,
"animaltypeid" bigint,
"breed"        varchar(255),
"name"         varchar(255),
"cost"         numeric(38, 2),
"character"    varchar(255),
"birthdate"    date
);

CREATE SEQUENCE IF NOT EXISTS hibernate_sequence START WITH 5 INCREMENT BY 1 ;
